-- 3. State vector fixtures (fixtures/state_vectors/*.bin)
--------------------------------------------------------------------------

T.describe("parity: state vectors", function()
  T.it("empty: decodes to {} and re-encodes byte-identical", function()
    local fixture = slurp(FIXTURES .. "/state_vectors/empty.bin")
    local sv, err = update.decode_state_vector(fixture)
    T.ok(sv ~= nil, err)
    T.eq(next(sv), nil)
    T.eq(update.encode_state_vector_from_table(sv), fixture)
  end)

  T.it("single_client: decodes to {1=5} and re-encodes byte-identical", function()
    local fixture = slurp(FIXTURES .. "/state_vectors/single_client.bin")
    local sv, err = update.decode_state_vector(fixture)
    T.ok(sv ~= nil, err)
    T.eq(sv[1], 5)
    T.eq(update.encode_state_vector_from_table(sv), fixture)
  end)

  T.it("multi_client: decodes to {1=5, 2=5} and re-encodes byte-identical", function()
    local fixture = slurp(FIXTURES .. "/state_vectors/multi_client.bin")
    local sv, err = update.decode_state_vector(fixture)
    T.ok(sv ~= nil, err)
    T.eq(sv[1], 5)
    T.eq(sv[2], 5)
    T.eq(update.encode_state_vector_from_table(sv), fixture)
  end)

  T.it("single_client: matches Lua-side encode of the same doc state", function()
    local fixture = slurp(FIXTURES .. "/state_vectors/single_client.bin")
    local d = doc_mod.new({ client_id = 1 })
    local t = doc_mod.get_text(d, "content")
    doc_mod.transact(d, function(txn) text.insert(t, txn, 0, "hello") end)
    T.eq(update.encode_state_vector(d), fixture)
  end)
end)

