-- 4. Sync protocol fixtures (fixtures/sync/*.bin)
--------------------------------------------------------------------------

T.describe("parity: sync messages", function()
  T.it("step1: read_message tags it 'step1' and payload decodes to {1=5}", function()
    local fixture = slurp(FIXTURES .. "/sync/step1.bin")
    local msg_type, payload = sync.read_message(fixture)
    T.eq(msg_type, "step1")
    local sv, err = update.decode_state_vector(payload)
    T.ok(sv ~= nil, err)
    T.eq(sv[1], 5)
  end)

  T.it("step1: Lua-produced message for the same doc state matches byte-for-byte", function()
    local fixture = slurp(FIXTURES .. "/sync/step1.bin")
    local d = doc_mod.new({ client_id = 1 })
    local t = doc_mod.get_text(d, "content")
    doc_mod.transact(d, function(txn) text.insert(t, txn, 0, "hello") end)
    T.eq(sync.write_step1(d), fixture)
  end)

  T.it("step2: read_message tags it 'step2' and applies to carry 'hello'", function()
    local fixture = slurp(FIXTURES .. "/sync/step2.bin")
    local msg_type, payload = sync.read_message(fixture)
    T.eq(msg_type, "step2")
    local d = doc_mod.new({ client_id = 99 })
    local t = doc_mod.get_text(d, "content")
    local applied, err = update.apply_v1(d, payload)
    T.ok(applied ~= nil, err)
    T.eq(text.to_string(t), "hello")
  end)

  T.it("update_msg: read_message tags it 'update' and applies to carry 'x'", function()
    local fixture = slurp(FIXTURES .. "/sync/update_msg.bin")
    local msg_type, payload = sync.read_message(fixture)
    T.eq(msg_type, "update")
    local d = doc_mod.new({ client_id = 99 })
    local t = doc_mod.get_text(d, "content")
    local applied, err = update.apply_v1(d, payload)
    T.ok(applied ~= nil, err)
    T.eq(text.to_string(t), "x")
  end)

  T.it("update_msg: Lua write_update wrapping the fixture's own update payload matches byte-for-byte", function()
    local fixture = slurp(FIXTURES .. "/sync/update_msg.bin")
    local _msg_type, payload = sync.read_message(fixture)
    T.eq(sync.write_update(payload), fixture)
  end)
end)

T.describe("parity: full_handshake (real yjs two-peer sync, replayed against Lua)", function()
  -- fixtures/sync/full_handshake/handshake.json: A ('hello from A', client 1)
  -- and B (empty, client 2) run the 3-message sync protocol to convergence,
  -- then A broadcasts a further local edit ('!!' appended) as an Update
  -- message. Every step below checks BOTH that Lua's own emitted message
  -- bytes match the corresponding fixture (encode parity) and that
  -- applying the fixture's own bytes drives Lua to the same state yjs
  -- reached (decode parity).
  local dir = FIXTURES .. "/sync/full_handshake"
  local msg1 = slurp(dir .. "/01_a_to_b_step1.bin")
  local msg2 = slurp(dir .. "/02_b_to_a_step2.bin")
  local msg3 = slurp(dir .. "/03_b_to_a_step1.bin")
  local msg4 = slurp(dir .. "/04_a_to_b_step2.bin")
  local msg5 = slurp(dir .. "/05_a_to_b_update.bin")

  T.it("full sequence converges both peers to 'hello from A!!'", function()
    local a = doc_mod.new({ client_id = 1 })
    local text_a = doc_mod.get_text(a, "content")
    doc_mod.transact(a, function(txn) text.insert(text_a, txn, 0, "hello from A") end)

    local b = doc_mod.new({ client_id = 2 })
    local text_b = doc_mod.get_text(b, "content")

    -- 1. A -> B step1: Lua's own emission must match the real yjs bytes.
    local step1 = sync.write_step1(a)
    T.eq(step1, msg1)

    -- 2. B handles the fixture's own step1 bytes (decode parity), replies
    -- with step2; Lua's reply must match the real yjs bytes (encode parity).
    local reply1, rerr1 = sync.handle_message(b, msg1)
    T.ok(reply1 ~= nil, rerr1)
    T.eq(reply1, msg2)

    -- 3. A applies the fixture's own step2 bytes; no reply expected (B had
    -- nothing new), content unchanged.
    local reply2, rerr2 = sync.handle_message(a, msg2)
    T.eq(reply2, nil)
    T.eq(rerr2, nil)
    T.eq(text.to_string(text_a), "hello from A")

    -- 4. B -> A step1: Lua's own emission must match the real yjs bytes.
    local step1b = sync.write_step1(b)
    T.eq(step1b, msg3)

    -- 5. A handles the fixture's own step1 bytes, replies with step2
    -- (carrying "hello from A"); Lua's reply must match the real yjs bytes.
    local reply3, rerr3 = sync.handle_message(a, msg3)
    T.ok(reply3 ~= nil, rerr3)
    T.eq(reply3, msg4)

    -- 6. B applies the fixture's own step2 bytes -- now has "hello from A".
    local reply4, rerr4 = sync.handle_message(b, msg4)
    T.eq(reply4, nil)
    T.eq(rerr4, nil)
    T.eq(text.to_string(text_b), "hello from A")

    -- 7. A makes a further local edit and broadcasts it as an Update
    -- message; Lua's own emission must match the real yjs bytes.
    local txn = doc_mod.transact(a, function(txn) text.insert(text_a, txn, 12, "!!") end)
    local update_bytes, uerr = update.encode_v1(a, txn)
    T.ok(update_bytes ~= nil, uerr)
    local update_msg = sync.write_update(update_bytes)
    T.eq(update_msg, msg5)

    -- 8. B applies the fixture's own update bytes -- both sides converge.
    local reply5, rerr5 = sync.handle_message(b, msg5)
    T.eq(reply5, nil)
    T.eq(rerr5, nil)

    T.eq(text.to_string(text_a), "hello from A!!")
    T.eq(text.to_string(text_b), "hello from A!!")
  end)
end)
